package com.personalstudyplanner.service;
import com.personalstudyplanner.model.*; import java.util.*;
public class PYQAnalyzer { private final Map<Integer,Set<String>> keywords=new HashMap<>(); public void addKeywords(int topicId,String... words){keywords.computeIfAbsent(topicId,k->new HashSet<>()).addAll(Arrays.stream(words).map(String::toLowerCase).toList());} public int classify(String question){String q=question.toLowerCase();return keywords.entrySet().stream().filter(e->e.getValue().stream().anyMatch(q::contains)).mapToInt(Map.Entry::getKey).findFirst().orElse(-1);} public Map<Integer,Integer> frequency(List<PYQQuestion> qs){Map<Integer,Integer> m=new HashMap<>();qs.forEach(q->m.merge(q.topicId(),1,Integer::sum));return m;} public Map<Integer,Long> yearsAppeared(List<PYQQuestion> qs){Map<Integer,Set<Integer>> s=new HashMap<>();qs.forEach(q->s.computeIfAbsent(q.topicId(),k->new HashSet<>()).add(q.sourceYear()));Map<Integer,Long> out=new HashMap<>();s.forEach((k,v)->out.put(k,(long)v.size()));return out;} }
